// Fetch Gemini response
const rawOutput = $input.first().json.output;

let parsed;

try {

    parsed = JSON.parse(rawOutput);

} catch (err) {

    return [
        {
            json: {
                success: false,
                error: "Failed to parse AI response.",
                raw_response: rawOutput,
                generated_at: new Date().toISOString()
            }
        }
    ];

}

return [
    {
        json: {

            success: true,

            service: $("Edit Fields").first().json.service,

            statusCode: $("Edit Fields").first().json.status,

            environment: $("Edit Fields").first().json.environment,

            incident: {

                severity: parsed.severity,

                confidence: parsed.confidence,

                rootCause: parsed.rootCause,

                businessImpact: parsed.businessImpact,

                recommendedActions: parsed.recommendedActions,

                preventiveMeasures: parsed.preventiveMeasures,

                estimatedRecoveryTime: parsed.estimatedRecoveryTime,

                summary: parsed.summary

            },

            generated_at: new Date().toISOString()

        }
    }
];
